// Lumenmorph and Slidebox are loaded for this playground.
const { trackPointer, enhanceSlideboxRange, enhanceSlideboxRangeFill } =
  LumenExample;
const controller = new AbortController();
const stopLight = trackPointer(document.querySelector(".lm-lab"));
const ranges = [...document.querySelectorAll("input[type=range]")].flatMap(
  (input) => [enhanceSlideboxRange(input), enhanceSlideboxRangeFill(input)],
);

(function (demo, signal) {
  const cards = [...demo.querySelectorAll(".notification")];
  const restore = demo.querySelector("[data-restore]");
  const status = () => {
    const count = cards.filter((card) => !card.hidden).length;
    demo.querySelector(".notification-status").textContent = count
      ? `${count} sample notification${count === 1 ? "" : "s"}`
      : "All clear. Enjoy the quiet.";
  };
  for (const card of cards)
    card.querySelector("[data-dismiss]").addEventListener(
      "click",
      () => {
        card.hidden = true;
        status();
        (
          cards.find((item) => !item.hidden)?.querySelector("[data-dismiss]") ??
          restore
        ).focus({ preventScroll: true });
      },
      { signal },
    );
  restore.addEventListener(
    "click",
    () => {
      for (const card of cards) card.hidden = false;
      status();
    },
    { signal },
  );
})(document.querySelector(".showcase-demo"), controller.signal);

window.addEventListener("pagehide", (event) => {
  if (!event.persisted) {
    controller.abort();
    stopLight();
    ranges.forEach((stop) => stop());
  }
});
